INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES ('mode', '东京MODE学园', '東京モード学園', '设计 / 时尚 / 美妆', '东京都新宿区西新宿1-7-3', '2027年度留学生费用须向入学咨询室索取当期《留学生入学要项》确认；官网公开页未给出可核对的统一学费表。', '因学科和修业年限不同，须按2027年度要项逐科确认。', '2027年4月海外出愿期为2026年5月1日至11月30日；海外特别入学要求12年教育并满足N1/N2、BJT 400或JPT 525等条件之一。', NULL, '官网未提供可用于本站的统一就业率统计；旧就业率和定点招聘说法已删除。', '以2027年度留学生入学要项为准。', '各学科授予称号须按课程认定与修业年限确认。', '本批未核实统一出勤率门槛。', '["服装设计","造型与美容","室内与平面设计","东京新宿校区"]'::jsonb, '[{"name":"昼间部专业课程","description":"服装、造型、美容及设计相关学科；实际招生学科与年限按2027要项。","duration":"依学科","totalCost":"待校方要项确认"}]'::jsonb, '{"enrollmentFee":"以2027年度留学生入学要项为准","admissionFee":"以2027年度留学生入学要项为准","annualTuition":"以2027年度留学生入学要项为准","facilitiesFee":"以2027年度留学生入学要项为准","practiceMaterialsFee":"以2027年度留学生入学要项为准","totalFirstYear":"以2027年度留学生入学要项为准"}'::jsonb, '["时尚与服装设计","美容造型","视觉与空间设计"]'::jsonb, '["校方列有提携企业学费免除及校内外奖学金，资格与金额以当期审查为准。"]'::jsonb) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES ('tsuji', '辻调理师专门学校（大阪／东京）', '辻調理師専門学校（大阪／東京）', '料理 / 甜点', '大阪 / 东京', '官网已发布2027年度大阪校与东京校入学要项；费用因学校、学科和课程而异，须按要项学费表确认，不沿用旧的140万～160万日元估算。', '按学校、学科和课程逐项确认。', '旧条目将调理师、制菓卫生师资格与所有课程混为一谈；现按具体学校和学科的2027要项确认。', NULL, '官网未提供可用于本站的统一就业率统计；旧就业率和定点招聘说法已删除。', '官网2027要项设学费分割缴纳说明，具体金额和期限依学校与入试区分。', '称号与国家资格报考资格依具体学科；不再概括为所有课程均可同时取得。', '本批未核实通用出勤率门槛。', '["调理","制菓","大阪校与东京校","2027年度入学要项已发布"]'::jsonb, '[{"name":"调理／制菓相关学科","description":"课程、年限、可取得资格和费用依大阪校或东京校2027要项。","duration":"依学科","totalCost":"按2027要项"}]'::jsonb, '{"enrollmentFee":"按2027年度大阪校或东京校入学要项确认","admissionFee":"按2027年度大阪校或东京校入学要项确认","annualTuition":"按2027年度大阪校或东京校入学要项确认","facilitiesFee":"按2027年度大阪校或东京校入学要项确认","practiceMaterialsFee":"按2027年度大阪校或东京校入学要项确认","totalFirstYear":"按2027年度大阪校或东京校入学要项确认"}'::jsonb, '["调理方向","制菓方向"]'::jsonb, '["校方设独自奖学金与学费减免制度，适用条件按2027要项。"]'::jsonb) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
