-- 2027资料核对第十九批：20条旧候选（保留更新13条、移除失真/错误归类7条）。
-- APPLIED 2026-11-18：13条更新经Supabase SQL应用，7条精确删除经服务角色REST应用并回查。
-- 删除目标仅限无法对应单一现行专门学校主体的明确slug；事务含目标记录数前置校验。
BEGIN;
DO $$ BEGIN
  IF (SELECT count(*) FROM "VocationalSchool" WHERE slug IN ('mode', 'tsuji', 'yamano-beauty', 'hollywood-beauty', 'tokyo-auto', 'esp-music', 'tokyo-tourism', 'tokyo-animal', 'tokyo-design', 'fca', 'ecc', 'seifu', 'yomiuri', 'digital-hollywood', 'tokyo-anime', 'yoyogi-anime', 'vantan-game', 'human-academy', 'ohara', 'aso')) <> 20 THEN
    RAISE EXCEPTION '第十九批目标记录不完整，事务已中止';
  END IF;
END $$;
DELETE FROM "VocationalSchool" WHERE slug IN ('digital-hollywood', 'tokyo-anime', 'yoyogi-anime', 'vantan-game', 'human-academy', 'ohara', 'aso');
COMMIT;
